package io.tuji.app;
import org.junit.*;
import static org.junit.Assert.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import org.json.*;

public class PhotoBundleTest {
 File root;@Before public void before()throws Exception{root=Files.createTempDirectory("tuji-test").toFile();}@After public void after(){PhotoBundle.deleteTree(root);}
 File source(String name,byte[] data)throws Exception{File f=new File(root,name);Files.write(f.toPath(),data);return f;}
 @Test public void roundTripKeepsAllBytesIncludingAppendedMotionData()throws Exception{
  byte[] bytes=new byte[2*1024*1024+777];new Random(42).nextBytes(bytes);File f=source("original",bytes),zip=new File(root,"photo.tuji.zip");PhotoBundle.pack(Arrays.asList(new PhotoBundle.Item(f,"实况.jpg","","",f.length())),zip,(d,t)->{});List<PhotoBundle.Item> items=PhotoBundle.unpack(zip,new File(root,"extracted"),(d,t)->{});assertEquals(1,items.size());assertEquals("实况.jpg",items.get(0).name);assertArrayEquals(bytes,Files.readAllBytes(items.get(0).file.toPath()));assertEquals(PhotoBundle.hash(f),items.get(0).sha256);
 }
 @Test public void originalSampleGpsAndRedactedSampleRemainDistinct()throws Exception{
  File dir=new File(System.getProperty("tuji.fixtures","")),yes=new File(dir,"has-gps.jpg"),no=new File(dir,"no-gps.jpg");Assume.assumeTrue(yes.isFile()&&no.isFile());
  double[] ll=ExifGps.read(yes);assertNotNull(ll);assertEquals(30.512630444444444,ll[0],1e-10);assertEquals(114.3313751111111,ll[1],1e-10);assertNull(ExifGps.read(no));
  File zip=new File(root,"sample.tuji.zip");PhotoBundle.pack(Arrays.asList(new PhotoBundle.Item(yes,"含定位.jpg","","",yes.length()),new PhotoBundle.Item(no,"无定位.jpg","","",no.length())),zip,(d,t)->{});List<PhotoBundle.Item> files=PhotoBundle.unpack(zip,new File(root,"result"),(d,t)->{});assertEquals(PhotoBundle.hash(yes),PhotoBundle.hash(files.get(0).file));assertEquals(PhotoBundle.hash(no),PhotoBundle.hash(files.get(1).file));assertArrayEquals(ll,ExifGps.read(files.get(0).file),0);assertNull(ExifGps.read(files.get(1).file));
 }
 @Test public void rejectsUnsafePaths(){for(String path:new String[]{"../escape","photos/../escape","photos/a/../../escape","photos/a\\b","/photos/a","photos//a","photos/./a"})assertFalse(path,PhotoBundle.validPath(path));assertTrue(PhotoBundle.validPath("photos/1/image.jpg"));}
 File manual(String path,long size,String hash,byte[] data)throws Exception{File z=new File(root,"bad.zip");try(ZipOutputStream out=new ZipOutputStream(new FileOutputStream(z))){out.putNextEntry(new ZipEntry("manifest.json"));out.write(new JSONObject().put("format","tuji.photo-bundle").put("version",1).put("files",new JSONArray().put(new JSONObject().put("path",path).put("name","a.jpg").put("size",size).put("sha256",hash))).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));out.closeEntry();out.putNextEntry(new ZipEntry(path));out.write(data);out.closeEntry();}return z;}
 @Test public void rejectsHashMismatchAndCleansExtraction()throws Exception{File dir=new File(root,"stage"),z=manual("photos/1/a.jpg",3,"0".repeat(64),new byte[]{1,2,3});assertThrows(Exception.class,()->PhotoBundle.unpack(z,dir,(d,t)->{}));assertFalse(dir.exists());}
 @Test public void rejectsSizeMismatch()throws Exception{File z=manual("photos/1/a.jpg",4,"0".repeat(64),new byte[]{1,2,3});assertThrows(Exception.class,()->PhotoBundle.unpack(z,new File(root,"stage"),(d,t)->{}));}
 @Test public void rejectsTraversalFromManifest()throws Exception{File z=manual("../escape",3,"0".repeat(64),new byte[]{1,2,3});assertThrows(Exception.class,()->PhotoBundle.unpack(z,new File(root,"stage"),(d,t)->{}));assertFalse(new File(root,"escape").exists());}
 @Test public void cancellationLeavesNoPartFile()throws Exception{File f=source("x",new byte[262144]),zip=new File(root,"cancel.tuji.zip");assertThrows(Exception.class,()->PhotoBundle.pack(Arrays.asList(new PhotoBundle.Item(f,"x.jpg","","",f.length())),zip,(d,t)->{throw new IOException("cancel");}));assertFalse(zip.exists());assertFalse(new File(zip+".part").exists());}
 @Test public void ordinaryZipIsNotImported()throws Exception{File z=new File(root,"ordinary.zip");try(ZipOutputStream out=new ZipOutputStream(new FileOutputStream(z))){out.putNextEntry(new ZipEntry("image.jpg"));out.write(1);}assertThrows(Exception.class,()->PhotoBundle.unpack(z,new File(root,"stage"),(d,t)->{}));}
 @Test public void batchThirtyPhotosOverFiveHundredMegabytes()throws Exception{Assume.assumeTrue(Boolean.getBoolean("tuji.stress"));File original=new File(root,"source");byte[] block=new byte[1024*1024];new Random(19).nextBytes(block);try(OutputStream out=new FileOutputStream(original)){for(int i=0;i<17;i++)out.write(block);}List<PhotoBundle.Item> items=new ArrayList<>();for(int i=0;i<30;i++)items.add(new PhotoBundle.Item(original,"IMG-"+i+".jpg","","",original.length()));File zip=new File(root,"batch.tuji.zip");PhotoBundle.pack(items,zip,(d,t)->{});assertTrue(zip.length()>500L*1024*1024);List<PhotoBundle.Item> result=PhotoBundle.unpack(zip,new File(root,"stage"),(d,t)->{});assertEquals(30,result.size());String hash=PhotoBundle.hash(original);for(PhotoBundle.Item f:result)assertEquals(hash,PhotoBundle.hash(f.file));}

 @Test public void v2ExtractsOnlyRootPhotosWithNoManifest()throws Exception{File f=source("source",new byte[]{1,2,3}),zip=new File(root,"flat.tuji.zip");PhotoBundle.pack(Arrays.asList(new PhotoBundle.Item(f,"IMG.jpg","","",3)),zip,(d,t)->{});try(ZipFile z=new ZipFile(zip)){assertEquals("TUJI_PHOTO_BUNDLE_V2",z.getComment());assertEquals(1,z.size());assertNotNull(z.getEntry("IMG.jpg"));assertNull(z.getEntry("manifest.json"));assertNotNull(z.getEntry("IMG.jpg").getExtra());}java.nio.file.Path evidence=java.nio.file.Paths.get(System.getProperty("tuji.fixtures"),"v2-flat-evidence.zip");java.nio.file.Files.copy(zip.toPath(),evidence,java.nio.file.StandardCopyOption.REPLACE_EXISTING);}
 @Test public void windowsNamesAreSafeAndUnique(){Set<String> used=new HashSet<>();assertEquals("a.jpg",PhotoBundle.uniqueName("a.jpg",used));assertEquals("A_2.JPG",PhotoBundle.uniqueName("A.JPG",used));assertEquals("_CON.jpg",PhotoBundle.windowsName("CON.jpg"));assertEquals("a_b_.jpg",PhotoBundle.windowsName("a:b?.jpg"));assertEquals("test",PhotoBundle.windowsName("test. "));}
 @Test public void v2SameNamesRoundTripWithoutOverwriting()throws Exception{File a=source("one",new byte[]{1}),b=source("two",new byte[]{2}),zip=new File(root,"same.tuji.zip");PhotoBundle.pack(Arrays.asList(new PhotoBundle.Item(a,"same.jpg","","",1),new PhotoBundle.Item(b,"same.jpg","","",1)),zip,(d,t)->{});try(ZipFile z=new ZipFile(zip)){assertNotNull(z.getEntry("same.jpg"));assertNotNull(z.getEntry("same_2.jpg"));}List<PhotoBundle.Item> files=PhotoBundle.unpack(zip,new File(root,"same-stage"),(d,t)->{});assertEquals(2,files.size());assertArrayEquals(new byte[]{1},Files.readAllBytes(files.get(0).file.toPath()));assertArrayEquals(new byte[]{2},Files.readAllBytes(files.get(1).file.toPath()));}
 @Test public void stillReadsValidV1Manifest()throws Exception{byte[] bytes={1,2,3};File f=source("original-v1",bytes);File z=manual("photos/1/photo.jpg",bytes.length,PhotoBundle.hash(f),bytes);List<PhotoBundle.Item> items=PhotoBundle.unpack(z,new File(root,"legacy"),(d,t)->{});assertEquals(1,items.size());assertArrayEquals(bytes,Files.readAllBytes(items.get(0).file.toPath()));}
}
